public class TransferServiceTest {

    @Test
    void shouldRejectNegativeOrZeroAmount() {
        var accountRepo = new InMemoryAccountRepo();
        var ledgerRepo = new InMemoryLedgerRepo();
        var service = new TransferService(accountRepo, ledgerRepo);

        assertThatThrownBy(() -> service.transfer(1L, 2L, BigDecimal.ZERO, "k1"))
