    }
}

package com.bank.account;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * ВНИМАНИЕ: Данный класс содержит антипаттерны с собеседования в Райффайзен:
 * 1. Использование TreeMap с ключом Date (транзакции в одну мс затирают друг друга!).
 * 2. Хранение balance как double (потеря точности в финансах).
 * 3. Утечка внутренней коллекции транзакций и публичные мутабельные поля.
 */
public class Account {
    public String id;
    public double balance;
    public Map<Date, TransactionRecord> transactions;

    public record TransactionRecord(long timestamp, BigDecimal amount, String type) {}

    public Account(String id) {
        this.id = id;
        this.balance = 0.0;
        this.transactions = new TreeMap<>();
    }

    public void deposit(BigDecimal amount) {
        this.balance += amount.doubleValue();
        Date now = new Date();
        this.transactions.put(now, new TransactionRecord(now.getTime(), amount, "DEPOSIT"));
    }

    public void withdraw(BigDecimal amount) {
        this.balance -= amount.doubleValue();
        Date now = new Date();
        this.transactions.put(now, new TransactionRecord(now.getTime(), amount.negate(), "WITHDRAW"));
    }

    public BigDecimal getBalance() {
        return BigDecimal.valueOf(balance);
    }

    public List<TransactionRecord> getTransactions() {
        return new ArrayList<>(transactions.values());
    }
}

package com.bank.account;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.assertThat;

public class AccountTest {

    @Test
    void shouldRetainAllTransactionsEvenInSameMillisecond() {
        Account acc = new Account("acc-1");
        acc.deposit(BigDecimal.valueOf(100));
        acc.withdraw(BigDecimal.valueOf(70));
        assertThat(acc.getTransactions()).hasSize(2);
        assertThat(acc.getBalance()).isEqualByComparingTo(BigDecimal.valueOf(30));
    }
}
